(function(E){ const x = E["mkt-m2"] = E["mkt-m2"] || {units:{}}; x.units["mkt-cp-2"] = {"exit":{"id":"c-mkt-cp-2-x","course":"marketing","unit":"mkt-cp-2","type":"exit","items":[{"from":"mkt-1","kind":"blank","prompt":"A few years ago, we ___ have a web shop.","options":["didn't use to","don't use to","weren't used to"],"correct":0,"point":2,"why":{"en":"didn't use to: in the negative, did takes use to. 'Don't use to' is the present, and 'weren't used to' means 'weren't familiar with'.","tr":"didn't use to: olumsuzda did 'use to' alır. 'Don't use to' şimdiki zamandır; 'weren't used to' 'alışkın değildik' demektir.","fa":"didn't use to درست است، چون در منفی بعد از did شکل use to می‌آید. don't use to زمان حال است و weren't used to یعنی «عادت نداشتیم»."}},{"from":"mkt-2","kind":"blank","prompt":"Half ___ our web-shop customers are new to the brand.","options":["from","in","of"],"correct":2,"point":2,"why":{"en":"of: 'half of' + the group. 'From' and 'in' don't make this pattern.","tr":"of: 'half of' + grup. 'From' ve 'in' bu kalıbı kurmaz.","fa":"of درست است، چون الگو half of و بعد گروه است. from و in این الگو را نمی‌سازند."}},{"from":"mkt-3","kind":"mcq","prompt":"Which sentence means \"it is not allowed\"?","options":["You don't have to mention the price.","You mustn't mention the price.","You must mention the price."],"correct":1,"point":2,"why":{"en":"'You mustn't mention the price' means it is not allowed. 'Don't have to' means it is optional, and 'must' means it is required.","tr":"'You mustn't mention the price' yasak demektir. 'Don't have to' isteğe bağlı, 'must' zorunlu demektir.","fa":"«You mustn't mention the price» یعنی ممنوع است. don't have to یعنی اختیاری است و must یعنی واجب."}},{"from":"mkt-5","kind":"mcq","prompt":"\"Dries in an hour\" is a feature. What comes next?","options":["So you can pack it on the same day.","Our brand is premium.","Buy now."],"correct":0,"point":1,"why":{"en":"'So you can pack it on the same day' is the benefit that follows the feature. 'Premium' is a claim, and 'Buy now' skips the benefit.","tr":"'So you can pack it on the same day' özellikten sonra gelen faydadır. 'Premium' bir iddiadır; 'Buy now' faydayı atlar.","fa":"«So you can pack it on the same day» فایده‌ای است که بعد از ویژگی می‌آید. premium ادعاست و Buy now فایده را جا می‌اندازد."}},{"from":"mkt-5","kind":"blank","prompt":"The buyer wants a ___ test in twelve stores.","options":["three-month","three-months","three months"],"correct":0,"point":2,"why":{"en":"three-month: a number before a noun is an adjective: hyphen, and no -s. 'Three-months' adds -s, and 'three months' can't sit before test.","tr":"three-month: isimden önce gelen sayı sıfattır: tire ve -s yok. 'Three-months' -s ekler; 'three months' test'ten önce gelemez.","fa":"three-month درست است، چون عدد قبل از اسم صفت است: با خط تیره و بدون ‎-s. three-months ‎-s دارد و three months قبل از test نمی‌آید."}},{"from":"mkt-6","kind":"mcq","prompt":"Which is the best first line for cafe owners?","options":["We love coffee!","Check out our new post.","What do your customers taste first?"],"correct":2,"point":1,"why":{"en":"'What do your customers taste first?' speaks to the café owner's own business. 'We love coffee!' and 'Check out our new post' are about you.","tr":"'What do your customers taste first?' kafe sahibinin kendi işine seslenir. 'We love coffee!' ve 'Check out our new post' seninle ilgilidir.","fa":"«What do your customers taste first?» با کسب‌وکار خود صاحب کافه حرف می‌زند. «We love coffee!» و «Check out our new post» درباره‌ی خودت هستند."}},{"from":"mkt-7","kind":"blank","prompt":"The samples ___ by courier last week.","options":["were sent","sent","were send"],"correct":0,"point":2,"why":{"en":"were sent: the samples received the action last week, so were + past participle. 'Sent' alone says the samples sent something; 'were send' drops the participle.","tr":"were sent: numuneler geçen hafta eylemi aldı, bu yüzden were + üçüncü hâl. Tek başına 'sent' numunelerin bir şey gönderdiğini söyler; 'were send' üçüncü hâli düşürür.","fa":"were sent درست است، چون نمونه‌ها هفته‌ی پیش فرستاده شدند و were و اسم مفعول لازم است. sent تنها یعنی نمونه‌ها چیزی فرستاده‌اند و were send اسم مفعول ندارد."}},{"from":"mkt-8","kind":"blank","prompt":"Weekly orders rose from 40 ___ 90.","options":["by","to","at"],"correct":1,"point":2,"why":{"en":"to: 'from 40 to 90' gives the start and the new level. 'By' would give the size of the rise, and 'at' doesn't pair with from.","tr":"to: 'from 40 to 90' başlangıcı ve yeni seviyeyi verir. 'By' artışın miktarını verir; 'at' from ile eşleşmez.","fa":"to درست است، چون from 40 to 90 شروع و سطح جدید را می‌گوید. by مقدار افزایش را می‌گوید و at با from جفت نمی‌شود."}}]},"writing":{"id":"c-mkt-cp-2-w","title":{"en":"A page a careful buyer can trust","tr":"Dikkatli bir alıcının güveneceği sayfa","fa":"صفحه‌ای که خریدار دقیق به آن اعتماد کند"},"course":"marketing","unit":"mkt-cp-2","type":"writing","difficulty":"medium","modelBy":"FEschool","portfolio":"mkt-final-2","prompt":{"en":"Write a product page for a careful store buyer (80-110 words), for your own product or this hotel towel: 600 g/m²; 100% cotton; tested for harmful substances (OEKO-TEX); not organic; lab-tested to 150 washes at 60°C; web-shop results: weekly orders rose from 40 to 90 in three months; nearly one in five buyers ordered again; reports on request.","tr":"Dikkatli bir mağaza alıcısı için ürün sayfası yaz (80-110 kelime), kendi ürünün ya da şu otel havlusu için: 600 g/m²; %100 pamuk; zararlı maddeler için test edildi (OEKO-TEX); organik değil; laboratuvarda 60°C'de 150 yıkamaya kadar test edildi; web mağazası sonuçları: haftalık siparişler üç ayda 40'tan 90'a çıktı; alıcıların beşte birine yakını yeniden sipariş verdi; raporlar talep üzerine.","fa":"برای یک خریدار دقیق فروشگاه صفحه‌ی محصول بنویس (۸۰ تا ۱۱۰ کلمه)، برای محصول خودت یا این حوله‌ی هتلی: ۶۰۰ گرم بر متر مربع؛ ۱۰۰ درصد پنبه؛ آزمایش‌شده برای مواد مضر (OEKO-TEX)؛ ارگانیک نیست؛ در آزمایشگاه تا ۱۵۰ شست‌وشو در ۶۰ درجه آزمایش شده؛ نتایج فروشگاه اینترنتی: سفارش هفتگی در سه ماه از ۴۰ به ۹۰ رسید؛ نزدیک به یک نفر از هر پنج خریدار دوباره سفارش داد؛ گزارش‌ها در صورت درخواست."},"model":"Hotel bath towel, 600 g/m²\nMade from 100% cotton and tested for harmful substances (OEKO-TEX). It is not organic.\nThick and absorbent, it was tested to 150 washes at 60°C in our lab, so it lasts in a busy laundry.\nResults from our web shop: in three months, weekly orders have risen from 40 to 90, and nearly one in five buyers has ordered again.\nAll test reports are available on request. Message us, and we will send them today.","frame":"___, ___\nMade from ___ and tested for ___ (___). It is not ___.\n___, it was tested to ___, so ___.\nResults from ___: in ___, ___ have risen from ___ to ___, and nearly ___.\n___ are available on request. ___.","words":[{"word":"made from"},{"word":"risen from"},{"word":"nearly"}],"minWords":70,"minSentences":5,"rubric":["Task done: product, material, label and what it is not, one tested fact, one honest results line","Organised: facts, proof, results, where to get documents","Language: passive for facts; rise from... to; honest approximations","Tone: precise and calm, for a careful buyer"],"rubricI18n":{"tr":["Görev: ürün, malzeme, etiket ve ne olmadığı, test edilmiş bir bilgi, dürüst bir sonuç satırı","Düzen: bilgiler, kanıt, sonuçlar, belgelerin nereden alınacağı","Dil: bilgiler için edilgen; rise from... to; dürüst yaklaşık rakamlar","Üslup: kesin ve sakin, dikkatli bir alıcı için"],"fa":["کامل بودن کار: محصول، جنس، برچسب و آنچه محصول نیست، یک واقعیت آزمایش‌شده، یک خط نتیجه‌ی صادقانه","نظم: واقعیت‌ها، مدرک، نتایج، راه دریافت مدارک","زبان: مجهول برای واقعیت‌ها؛ rise from... to؛ تقریب صادقانه","لحن: دقیق و آرام، برای خریدار دقیق"]},"parts":[{"t":{"en":"Product and material","tr":"Ürün ve malzeme","fa":"محصول و جنسش"},"find":["made from","cotton","material"],"sample":"hotel towel, 600 g/m² · 100% cotton"},{"t":{"en":"The label, and what it is not","tr":"Etiket ve ne olmadığı","fa":"برچسب و اینکه چه چیزی نیست"},"find":["is not","isn't","not organic","not certified"],"sample":"tested for harmful substances (OEKO-TEX) · not organic"},{"t":{"en":"One tested fact","tr":"Test edilmiş bir bilgi","fa":"یک واقعیت آزمایش‌شده"},"find":["tested to","150 washes","washes","in our lab","lab-tested"],"sample":"lab-tested to 150 washes at 60°C"},{"t":{"en":"One honest results line","tr":"Dürüst bir sonuç satırı","fa":"یک خط صادقانه درباره‌ی نتیجه"},"find":["risen from","rose from","nearly","results","orders"],"sample":"weekly orders rose from 40 to 90 in three months · nearly one in five ordered again"},{"t":{"en":"Where to get the reports","tr":"Raporların nereden alınacağı","fa":"گزارش‌ها را از کجا می‌شود گرفت"},"find":["on request","reports","report","message us"],"sample":"reports on request"}]},"speaking":{"id":"mkt-cp-2","course":"marketing","unit":"mkt-cp-2","topic":{"en":"One number, explained to a buyer","tr":"Bir rakamı alıcıya açıklamak","fa":"توضیح یک عدد برای خریدار"},"warmup":{"en":"What makes you trust a new supplier or shop?","tr":"Yeni bir tedarikçiye ya da mağazaya güvenmeni ne sağlar?","fa":"چه چیزی باعث می‌شود به یک فروشنده‌ی تازه اعتماد کنی؟"},"questions":[{"en":"A buyer asks: \"How is the web shop doing?\" Answer with one trend and one honest weak point.","tr":"Bir alıcı soruyor: \"How is the web shop doing?\" Bir eğilim ve dürüst bir zayıf noktayla cevap ver.","fa":"خریداری می‌پرسد: «How is the web shop doing?» با یک روند و یک نقطه‌ضعف صادقانه جواب بده."},{"en":"Explain what \"nearly one in five buyers ordered again\" means for this buyer.","tr":"\"Nearly one in five buyers ordered again\" ifadesinin bu alıcı için ne anlama geldiğini açıkla.","fa":"توضیح بده «nearly one in five buyers ordered again» برای این خریدار چه معنایی دارد."},{"en":"The buyer asks: \"Can you prove the 150 washes?\" Answer.","tr":"Alıcı soruyor: \"Can you prove the 150 washes?\" Cevap ver.","fa":"خریدار می‌پرسد: «Can you prove the 150 washes?» جواب بده."}],"followups":[{"en":"Say it again in 45 seconds, with the same three points.","tr":"Aynı üç noktayla 45 saniyede yeniden söyle.","fa":"با همان سه نکته در ۴۵ ثانیه دوباره بگو."}],"expressions":[{"phrase":"Since December, ... has risen from... to...","meaning":{"en":"Gives a trend.","tr":"Bir eğilim verir.","fa":"یک روند را می‌گوید."}},{"phrase":"What that means for you is...","meaning":{"en":"Links the number to the listener.","tr":"Rakamı dinleyene bağlar.","fa":"عدد را به کار شنونده ربط می‌دهد."}},{"phrase":"The test report is available today.","meaning":{"en":"Offers proof.","tr":"Kanıt sunar.","fa":"مدرک پیشنهاد می‌دهد."}}],"model":"Since December, weekly orders in our web shop have risen from 40 to 90. To be honest, that's slower than we hoped. But nearly one in five buyers has ordered again, and what that means for you is simple: people who try the towel come back. And yes, we can prove the 150 washes. The test report is available today.","selfCheck":[{"en":"I gave one trend with from... to.","tr":"from... to ile bir eğilim verdim.","fa":"با from... to یک روند گفتم."},{"en":"I was honest about one weak point.","tr":"Bir zayıf nokta konusunda dürüst oldum.","fa":"درباره‌ی یک نقطه‌ضعف صادق بودم."},{"en":"I offered proof.","tr":"Kanıt sundum.","fa":"مدرک پیشنهاد دادم."},{"en":"Round 3 fitted in the time.","tr":"3. tur süreye sığdı.","fa":"دور سوم را در زمان تعیین‌شده تمام کردم."}]}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
